package externalconfig

import (
	"crypto/sha256"
	"encoding/json"
	"errors"
	"fmt"
)

// Complete checks the control-plane pieces generated by official v0.5.5 for
// External mode. User inbounds, routes and explicit ports remain official-owned.
func Complete(data []byte) (bool, error) {
	var config struct {
		API struct {
			Tag      string
			Services []string
		}
		Metrics  struct{ Tag, Listen string }
		Inbounds []struct {
			Tag, Protocol, Listen string
			Port                  any
		}
		Routing struct {
			Rules []struct {
				Type        string
				InboundTag  []string
				OutboundTag string
			}
		}
	}
	if err := json.Unmarshal(data, &config); err != nil {
		return false, err
	}
	apiInbound, apiRoute := false, false
	for _, inbound := range config.Inbounds {
		if inbound.Tag != "api" {
			continue
		}
		port, _ := inbound.Port.(float64)
		if apiInbound || inbound.Protocol != "dokodemo-door" || inbound.Listen != "127.0.0.1" || port < 1 || port > 65535 {
			return false, errors.New("api inbound conflicts with official External control configuration")
		}
		apiInbound = true
	}
	for _, rule := range config.Routing.Rules {
		for _, tag := range rule.InboundTag {
			apiRoute = apiRoute || (tag == "api" && rule.OutboundTag == "api" && rule.Type == "field")
		}
	}
	services := map[string]bool{}
	for _, service := range config.API.Services {
		services[service] = true
	}
	return config.API.Tag == "api" && services["HandlerService"] && services["LoggerService"] && services["StatsService"] && services["RoutingService"] && config.Metrics.Tag != "" && config.Metrics.Listen != "" && apiInbound && apiRoute, nil
}

// UserConfigHash protects all fields outside the official system-config
// operation. This persisted fingerprint lets a retry prove it is accepting
// only its own control-plane repair, without storing user credentials.
func UserConfigHash(data []byte) (string, error) {
	var config map[string]any
	if err := json.Unmarshal(data, &config); err != nil {
		return "", err
	}
	for _, key := range []string{"api", "metrics", "policy", "stats"} {
		delete(config, key)
	}
	if inbounds, ok := config["inbounds"].([]any); ok {
		kept := []any{}
		for _, inbound := range inbounds {
			item, _ := inbound.(map[string]any)
			if item["tag"] != "api" {
				kept = append(kept, inbound)
			}
		}
		config["inbounds"] = kept
	}
	if routing, ok := config["routing"].(map[string]any); ok {
		if rules, ok := routing["rules"].([]any); ok {
			kept := []any{}
			for _, rule := range rules {
				item, _ := rule.(map[string]any)
				tags, _ := item["inboundTag"].([]any)
				if len(tags) == 1 && tags[0] == "api" && item["outboundTag"] == "api" {
					continue
				}
				kept = append(kept, rule)
			}
			if len(kept) == 0 {
				delete(routing, "rules")
			} else {
				routing["rules"] = kept
			}
		}
		if len(routing) == 0 {
			delete(config, "routing")
		}
	}
	encoded, err := json.Marshal(config)
	if err != nil {
		return "", err
	}
	return fmt.Sprintf("%x", sha256.Sum256(encoded)), nil
}

// Settings uses the official system-config readback to preserve explicit ports.
func Settings(current map[string]any) map[string]any {
	result := make(map[string]any, len(current))
	for key, value := range current {
		result[key] = value
	}
	result["metrics_enabled"], result["grpc_enabled"], result["stats_enabled"] = true, true, true
	if value, ok := result["metrics_listen"].(string); !ok || value == "" {
		result["metrics_listen"] = "127.0.0.1:38889"
	}
	if value, ok := result["grpc_port"].(float64); !ok || value < 1 {
		result["grpc_port"] = 46736
	}
	return result
}
